'use strict';

const fs = require('node:fs');
const path = require('node:path');

const { resolveD1Target } = require('./cloudflare-d1-target.cjs');
const { REQUIRED_PREVIEW_COLUMNS, buildPreviewSchemaCheckSql } = require('../e2e/lib/preview-schema-preflight.js');

// The read-only query surface is intentionally narrower than the migration
// planner: the only statements this repository may send through `cf d1 query`
// are the exact preview schema-check statements generated by
// e2e/lib/preview-schema-preflight.js. Keeping the allowlist on the plan lets
// cloudflare-cf-runner.cjs fail closed on anything else without knowing the
// template itself.
function previewSchemaCheckQueries(columns = REQUIRED_PREVIEW_COLUMNS) {
  return Object.freeze(columns.map((column) => buildPreviewSchemaCheckSql([column])));
}

function planD1Query(source, environment, sql, allowedSql) {
  if (environment !== 'preview') {
    // This surface only exists to verify preview schema state before E2E; a
    // production read through cf is out of scope for Phase D (JSMKC#4240).
    throw new Error('the cf d1 query plan is preview-only');
  }

  const target = resolveD1Target(source, environment);
  const args = ['d1', 'query', target.databaseId, '--sql', sql];

  return Object.freeze({
    command: 'cf',
    args: Object.freeze(args),
    environment: target.environment,
    operation: 'query',
    databaseId: target.databaseId,
    sql,
    allowedSql: Object.freeze([...allowedSql]),
  });
}

function parseCliOptions(argv = process.argv.slice(2)) {
  if (argv.length !== 1) {
    throw new Error('usage: node scripts/cloudflare-d1-query-plan.cjs <preview>');
  }
  return { environment: argv[0] };
}

function main() {
  const { environment } = parseCliOptions();
  const configPath = path.resolve(__dirname, '..', 'wrangler.toml');
  const source = fs.readFileSync(configPath, 'utf8');
  const allowed = previewSchemaCheckQueries();
  const plan = planD1Query(source, environment, allowed[0], allowed);
  process.stdout.write(`${JSON.stringify(plan)}\n`);
}

if (require.main === module) {
  try {
    main();
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`cloudflare-d1-query-plan: ${message}\n`);
    process.exitCode = 1;
  }
}

module.exports = {
  planD1Query,
  previewSchemaCheckQueries,
};
